</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  // Horizontal bullet/range chart showing four scenarios
  var scenarios=[
    {label:"Tail risk: ceasefire collapse",low:100,mid:110,high:120,fill:"#8a3030"},
    {label:"Risk case: talks stall",low:88,mid:93,high:98,fill:"#6b7280"},
    {label:"Base case: slow negotiation",low:83,mid:90,high:97,fill:"#4a5568"},
    {label:"Constructive: rapid deal",low:78,mid:83,high:90,fill:"#3a7a55"}
  ];
  var n=scenarios.length;
  var margin={left:200,right:80,top:24,bottom:36};
  var W=680,H=300;
  var PW=W-margin.left-margin.right;
  var rowH=(H-margin.top-margin.bottom)/n;
  var minV=70,maxV=125;
  function xS(v){return margin.left+(v-minV)/(maxV-minV)*PW;}
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("xmlns","http://www.w3.org/2000/svg");
  function el(tag,attrs){var e=document.createElementNS("http://www.w3.org/2000/svg",tag);for(var k in attrs)e.setAttribute(k,attrs[k]);return e;}
  function txt(s,attrs){var e=el("text",attrs);e.textContent=s;return e;}
  // Gridlines at $80,$90,$100,$110,$120
  [80,90,100,110,120].forEach(function(v){
    var gx=xS(v);
    svg.appendChild(el("line",{x1:gx,x2:gx,y1:margin.top,y2:H-margin.bottom,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt("$"+v,{x:gx,y:H-margin.bottom+12,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Current price reference
  var curX=xS(95);
  svg.appendChild(el("line",{x1:curX,x2:curX,y1:margin.top,y2:H-margin.bottom,stroke:"#1a3560","stroke-dasharray":"3,3","stroke-width":"1.2","stroke-opacity":"0.7"}));
  svg.appendChild(txt("Current ~$95",{x:curX-4,y:margin.top+10,"text-anchor":"end","font-size":"7.5","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Rows
  scenarios.forEach(function(s,i){
    var cy=margin.top+i*rowH+rowH/2;
    var barH=14;
    // Range bar
    svg.appendChild(el("rect",{x:xS(s.low),y:cy-barH/2,width:xS(s.high)-xS(s.low),height:barH,fill:s.fill,"fill-opacity":"0.18",rx:"2"}));
    // Mid dot
    svg.appendChild(el("circle",{cx:xS(s.mid),cy:cy,r:6,fill:s.fill}));
    // Label left
    svg.appendChild(txt(s.label,{x:margin.left-8,y:cy+4,"text-anchor":"end","font-size":"9","fill":"#444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    // Range label right
    svg.appendChild(txt("$"+s.low+"-$"+s.high,{x:xS(s.high)+6,y:cy+4,"text-anchor":"start","font-size":"8","fill":"#666","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Gold pill on base case mid
  var bcI=2;
  var bcy=margin.top+bcI*rowH+rowH/2;
  var bcMid=xS(scenarios[bcI].mid);
  var pillW=44,pillH=16;
  var pillX=bcMid-pillW/2;
  var pillY=bcy-pillH/2-18;
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(txt("$90 mid",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  var container=document.currentScript?document.currentScript.parentNode:null;
  if(container)container.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: HDQ scenario analysis based on Goldman Sachs, ING, Discovery Alert, and Commonwealth Bank of Australia analyst ranges, June 2026. &nbsp;|&nbsp; hdq.ca</div>
