<script>
(function(){
  // Indexed performance: TSX Composite and TSX Energy sub-index
  // Base = 100 on Mar 4, 2026
  // TSX Composite approximate weekly closes (indexed)
  // TSX Energy approximate weekly closes (indexed)
  var weeks=[
    {w:"Mar 4",comp:100.0,energy:100.0},
    {w:"Mar 9",comp:97.2,energy:106.4},
    {w:"Mar 16",comp:95.8,energy:111.2},
    {w:"Mar 23",comp:96.4,energy:114.8},
    {w:"Mar 30",comp:97.1,energy:117.3},
    {w:"Apr 6",comp:98.3,energy:122.6},
    {w:"Apr 13",comp:99.6,energy:116.9},
    {w:"Apr 20",comp:100.8,energy:110.4},
    {w:"Apr 27",comp:101.2,energy:114.7},
    {w:"May 4",comp:99.4,energy:120.8},
    {w:"May 11",comp:100.1,energy:118.3},
    {w:"May 18",comp:101.4,energy:113.6},
    {w:"May 25",comp:102.2,energy:116.1},
    {w:"Jun 3",comp:101.1,energy:117.4}
  ];
  var n=weeks.length;
  var margin={left:54,right:70,top:18,bottom:46};
  var W=680,H=300;
  var PW=W-margin.left-margin.right,PH=H-margin.top-margin.bottom;
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("xmlns","http://www.w3.org/2000/svg");
  function el(tag,attrs){var e=document.createElementNS("http://www.w3.org/2000/svg",tag);for(var k in attrs)e.setAttribute(k,attrs[k]);return e;}
  function txt(s,attrs){var e=el("text",attrs);e.textContent=s;return e;}
  var allV=[];
  weeks.forEach(function(d){allV.push(d.comp,d.energy);});
  var minV=Math.min.apply(null,allV)-3, maxV=Math.max.apply(null,allV)+3;
  function xS(i){return margin.left+i*(PW/(n-1));}
  function yS(v){return margin.top+PH-(v-minV)/(maxV-minV)*PH;}
  // Gridlines
  [95,100,105,110,115,120].forEach(function(v){
    if(v<minV||v>maxV)return;
    var gy=yS(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt(v,{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Base=100 reference line
  var refY=yS(100);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#7a3030","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("Base Mar 4",{x:650,y:refY-3,"text-anchor":"end","font-size":"7.5","fill":"#7a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Composite line
  var compPath="M "+xS(0)+","+yS(weeks[0].comp);
  for(var i=1;i<n;i++)compPath+=" L "+xS(i)+","+yS(weeks[i].comp);
  svg.appendChild(el("path",{d:compPath,fill:"none",stroke:"#6b7280","stroke-width":"1.8","stroke-dasharray":"5,3"}));
  // Energy line
  var engPath="M "+xS(0)+","+yS(weeks[0].energy);
  for(var i=1;i<n;i++)engPath+=" L "+xS(i)+","+yS(weeks[i].energy);
  svg.appendChild(el("path",{d:engPath,fill:"none",stroke:"#3a7a55","stroke-width":"2.2"}));
  // Event: Ceasefire 1 band Apr 13-27
  var b1x=xS(6), b2x=xS(8);
  svg.appendChild(el("rect",{x:b1x,y:margin.top,width:b2x-b1x,height:PH,fill:"#2e7d32","fill-opacity":"0.06"}));
  svg.appendChild(txt("CF-1",{x:(b1x+b2x)/2,y:margin.top+9,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // End series labels
  var lastComp=weeks[n-1].comp, lastEng=weeks[n-1].energy;
  var lx=xS(n-1);
  svg.appendChild(txt("Composite",{x:lx-4,y:yS(lastComp)-6,"text-anchor":"end","font-size":"8","fill":"#6b7280","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(txt("Energy",{x:lx-4,y:yS(lastEng)-6,"text-anchor":"end","font-size":"8","fill":"#3a7a55","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Gold pill on energy endpoint
  var pillW=52,pillH=16;
  var pillX=lx-pillW-6;
  var pillY=yS(lastEng)-pillH/2;
  svg.appendChild(el("circle",{cx:lx,cy:yS(lastEng),r:4,fill:"#3a7a55"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(txt("+17.4%",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // X labels every 3rd
  weeks.forEach(function(d,i){
    if(i%3===0||i===n-1){
      svg.appendChild(txt(d.w,{x:xS(i),y:H-margin.bottom+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    }
  });
  var container=document.currentScript?document.currentScript.parentNode:null;
  if(container)container.appendChild(svg);
})();
